if (-not (Get-Command Get-VM -ErrorAction SilentlyContinue)) { throw 'Get-VM is absent: the Hyper-V PowerShell module is not installed, so VMs cannot be enumerated - this host is UNENUMERABLE, not empty' }; $ErrorActionPreference = 'Stop'; function ShaOf($p) { (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLower() }; $name = 'enclave-snap-161ca971'; $gsf = 'C:\Users\claude\enclave-snap-161ca971\probe.vmgs'; $fw = 'C:\Users\claude\enclave-snap-161ca971\probe.bin'; $pipe = '\\.\pipe\snap-161ca971'; $vm = $null; $copied = $false; if (@(Get-VM -ErrorAction Stop | Where-Object {$_.Name -eq $name}).Count) { throw ('a VM named ' + $name + ' already exists: refusing to define a second one under the same name') }; if (Test-Path -LiteralPath $gsf) { throw ('a guest-state run copy already exists at ' + $gsf + ': refusing to overwrite a previous run''s store') }; try { $mod = 'C:\Program Files\Enclave\guest\hyperv.psm1'; $pin = '17ca4352c500d3498f71be420ddfa418c7ed1d1b5f455856c24e633a4635e49c'; $modSha = (ShaOf $mod); if ($modSha -ne $pin) { throw ('the module that DEFINES the VM hashes ' + $modSha + ', not the pinned ' + $pin) }; $utl = Join-Path (Split-Path -Parent $mod) 'utilities.psm1'; $utlSha = $null; if (Test-Path -LiteralPath $utl) { $utlSha = (ShaOf $utl) }; $pin = '517766e996ddb021594c0ae2c7a60688d4293e2ee9459f558f2a436e6da30731'; if ($utlSha -ne $pin) { throw ('utilities.psm1, which New-CustomVM imports, hashes ' + [string]$utlSha + ', not the pinned ' + $pin) }; Import-Module $mod -Force; if (-not (Get-Command New-CustomVM -EA SilentlyContinue)) { throw ('New-CustomVM is not defined after importing ' + $mod) }; $pin = 'cd5b06ded55dec460547531e47ca4de22775b9fc11e1d52d58c9e34e92df41e7'; $fwSha = (ShaOf $fw); if ($fwSha -ne $pin) { throw ('the IGVM hashes ' + $fwSha + ' at define time, not the pinned ' + $pin) }; $master = 'C:\ProgramData\Enclave\shield\type1.vmgs'; $masterSha = (ShaOf $master); $pin = 'e93237a717a7e0e9fa201db2b331d2ed480274bfa47145854ea3ba85852abb96'; if ($masterSha -ne $pin) { throw ('the guest-state master hashes ' + $masterSha + ', not the pinned ' + $pin) }; Copy-Item -LiteralPath $master -Destination $gsf; $copied = $true; $copySha = (ShaOf $gsf); if ($copySha -ne $masterSha) { throw ('the guest-state copy hashes ' + $copySha + ', not the master''s ' + $masterSha) }; 'started' | Set-Content -LiteralPath (Join-Path $Dir 'create-started.txt'); $ret = @(New-CustomVM -VMName $name -GuestStateIsolationEnabled $true -GuestStateIsolationType 1 -GuestStateIsolationMode 0 -FirmwareFile $fw -GuestStateFilePath $gsf -TpmEnabled $true -SecureBootEnabled $false -Com1 $true -Memory (2048 * 1MB) -VpCount 1); 'returned' | Set-Content -LiteralPath (Join-Path $Dir 'create-returned.txt'); $found = @(Get-VM -ErrorAction Stop | Where-Object {$_.Name -eq $name}); if ($found.Count -ne 1) { throw ('after New-CustomVM ' + $found.Count + ' VMs are named ' + $name + ', not exactly one') }; $vm = $found[0]; $vm.Id.Guid | Set-Content -LiteralPath (Join-Path $Dir 'owned-id.txt'); $retId = [string]($ret | Select-Object -Last 1); if (($retId -match '^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$') -and ($retId -ne $vm.Id.Guid)) { throw ('New-CustomVM returned ' + $retId + ' but the VM named ' + $name + ' has Id ' + $vm.Id.Guid) }; Set-VM -VM $vm -Notes 'private-snapshot-availability/snap-161ca971'; Set-VM -VM $vm -AutomaticStartAction Nothing -AutomaticStopAction TurnOff; $ns = 'root\virtualization\v2'; $csq = "select * from Msvm_ComputerSystem where Name = '" + $vm.Id.Guid + "'"; $vssd = Get-CimInstance -Namespace $ns -Query $csq | Get-CimAssociatedInstance -ResultClass Msvm_VirtualSystemSettingData -Association Msvm_SettingsDefineState; if (-not $vssd) { throw ('no Msvm_VirtualSystemSettingData for ' + $vm.Id.Guid) }; if ([int]$vssd.GuestStateIsolationType -ne 1) { throw ('GuestStateIsolationType reads back as ' + [string]$vssd.GuestStateIsolationType + ', not 1') }; if (-not [bool]$vssd.GuestStateIsolationEnabled) { throw 'GuestStateIsolationEnabled reads back False' }; if ([int64]$vssd.GuestFeatureSet -ne 513) { throw ('GuestFeatureSet reads back as 0x' + ('{0:x}' -f [int64]$vssd.GuestFeatureSet) + ', not 0x201') }; if ([int]$vssd.Vtl2AddressSpaceConfigurationMode -ne 0) { throw ('Vtl2AddressSpaceConfigurationMode reads back as ' + [string]$vssd.Vtl2AddressSpaceConfigurationMode + ': VTL2 auto placement on a fixed-GPA type-1 image') }; if ([string]$vssd.FirmwareFile -ne $fw) { throw ('FirmwareFile reads back as ' + [string]$vssd.FirmwareFile + ', not ' + $fw) }; $gsfBack = [System.IO.Path]::GetFullPath((Join-Path ([string]$vssd.GuestStateDataRoot) ([string]$vssd.GuestStateFile))); if ($gsfBack -ne [System.IO.Path]::GetFullPath($gsf)) { throw ('the VM''s guest state reads back as ' + $gsfBack + ', not the per-run copy ' + $gsf) }; $nics = @(Get-VMNetworkAdapter -VM $vm -EA SilentlyContinue); if ($nics.Count) { $nics | Remove-VMNetworkAdapter -Confirm:$false }; $nicsAfter = @(Get-VMNetworkAdapter -VM $vm -EA SilentlyContinue).Count; if ($nicsAfter -ne 0) { throw ([string]$nicsAfter + ' network adapter(s) remain: this guest has no NIC') }; Set-VMSecurity -VM $vm -VirtualizationBasedSecurityOptOut $true -EA Stop; $sec = $vssd | Get-CimAssociatedInstance -ResultClassName Msvm_SecuritySettingData; if (-not $sec) { throw 'no Msvm_SecuritySettingData on a type-1 VM: Windows makes a vTPM for a VBS VM, so this VM is not what it should be' }; if (-not [bool]$sec.VirtualizationBasedSecurityOptOut) { throw 'VirtualizationBasedSecurityOptOut reads back False: the guest VBS opt-out did not take' }; $grant = 'NT VIRTUAL MACHINE\' + $vm.Id.Guid + ':R'; $grants = @(); foreach ($gp in @($fw)) { & icacls $gp /grant $grant | Out-Null; if ($LASTEXITCODE -ne 0) { throw ('icacls could not grant the VM read access to ' + $gp + ' (exit ' + $LASTEXITCODE + ')') }; $grants += $gp }; $mediumPath = $null; $mediumSha = $null; if (@(Get-VMDvdDrive -VM $vm -EA SilentlyContinue).Count -ne 0) { throw 'linux-direct: